#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 1002 §4.2.12 name query request: transaction id 0x1234, broadcast flag set, one question.
    fn vector() -> Vec<u8> {
        vec![
            0x12, 0x34, 0x01, 0x10, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Nbns);
        let l = p.find_layer(ProtoId::Nbns).unwrap();
        assert_eq!(p.get(l, "NAME_TRN_ID").unwrap(), FieldValue::Uint(4660));
        assert_eq!(p.get(l, "FLAGS").unwrap(), FieldValue::Uint(272));
        assert_eq!(p.get(l, "QDCOUNT").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "ANCOUNT").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "NSCOUNT").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "ARCOUNT").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Nbns);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Nbns);
        let l = p.find_layer(ProtoId::Nbns).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Nbns, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
